const DAY=86400000;
const priorities=['Low','Normal','High','Urgent'];
const stamp=()=>new Date().toISOString();
const now=()=>formatStamp(stamp());
function formatStamp(value){const ms=Date.parse(value);return Number.isFinite(ms)?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(ms):'Not recorded'}
function dayKey(value=Date.now()){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-')}
function validDue(value){return value===''||(/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value)}
function ageHours(t,clock=Date.now()){const received=Date.parse(t.createdAt);return Number.isFinite(received)?Math.max(0,(clock-received)/3600000):null}
function isAged(t,clock=Date.now()){return t.status!=='Resolved'&&ageHours(t,clock)!==null&&ageHours(t,clock)>72}
function isPastDue(t,clock=Date.now()){return t.status!=='Resolved'&&!!t.dueBy&&t.dueBy<dayKey(clock)}
function elapsedHours(start,end){const a=Date.parse(start),b=Date.parse(end);return Number.isFinite(a)&&Number.isFinite(b)&&b>=a?(b-a)/3600000:null}
function legacyStamp(value){if(!value)return null;if(/^\d{4}-/.test(value))return Number.isFinite(Date.parse(value))?new Date(value).toISOString():null;const m=String(value).match(/(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec),?\s+(\d{1,2}):(\d{2})/);if(!m)return null;const month=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].indexOf(m[2]);let y=Number(dayKey().slice(0,4));let ms=Date.UTC(y,month,Number(m[1]),Number(m[3]),Number(m[4]));if(ms>Date.now()+DAY)ms=Date.UTC(y-1,month,Number(m[1]),Number(m[3]),Number(m[4]));return new Date(ms).toISOString()}

