function demonstrationExtras(clock=Date.now()){
const ago=h=>new Date(clock-h*3600000).toISOString();
const examples=[ticketExample(false,'HR-001040',ago(5)),ticketExample(true,'HR-001041',ago(2))];
const services=['weekly','salaried','holiday','po','details','probation'];
const jobs=[{age:170,duration:18,reply:2},{age:139,duration:31,reply:4},{age:114,duration:7,reply:1.5},{age:94,duration:26,reply:3},{age:65,duration:11,reply:2.5},{age:32,duration:8,reply:1}];
return examples.concat(jobs.map((job,i)=>{const createdAt=ago(job.age),resolvedAt=ago(job.age-job.duration),firstResponseAt=ago(job.age-job.reply);const cat=services[i],c=categories[cat];return {id:'HR-00009'+i,cat,title:'Completed example: '+c.name,submitter:'Jamie Taylor',employee:'Jamie Taylor',employeeNo:'DEMO-1042',site:'Demo site',department:'Demo department',owner:i%2?'Priya Shah':'Alex Morgan',status:'Resolved',priority:'Normal',dueBy:'',source:'Portal (example)',createdAt,created:formatStamp(createdAt),firstResponseAt,resolvedAt,fields:Object.fromEntries(c.fields.map(([key,label,type,value])=>[key,type==='select'?value[0]:value])),attachment:c.file,resolution:'The team checked the information, completed the requested action and confirmed the outcome with the requester.',messages:[{kind:'public',author:i%2?'Priya Shah':'Alex Morgan',at:formatStamp(firstResponseAt),text:'We have the information needed and are checking your request.'},{kind:'public',author:i%2?'Priya Shah':'Alex Morgan',at:formatStamp(resolvedAt),text:'The requested action is complete. Please reply on this ticket if anything needs checking.'}],history:[{at:formatStamp(createdAt),text:'Fictional request received.'},{at:formatStamp(resolvedAt),text:'Fictional request resolved.'}]}}));
}
function seed(){const clock=Date.now();const ages=[12,38,58,83,101,127];return baseSeed().map((t,i)=>{t.createdAt=new Date(clock-ages[i]*3600000).toISOString();t.created=formatStamp(t.createdAt);t.firstResponseAt=i>0?new Date(Date.parse(t.createdAt)+4*3600000).toISOString():null;t.resolvedAt=null;t.dueBy=i===3?dayKey(clock-DAY):i===1?dayKey(clock+DAY):'';t.priority=i===3?'High':'Normal';t.messages.forEach(m=>m.at=formatStamp(t.firstResponseAt||t.createdAt));t.history.forEach(h=>h.at=t.created);return t}).concat(demonstrationExtras(clock))}
function normaliseState(data){if(!data||!Array.isArray(data.tickets))return {tickets:seed(),next:1043,draft:null,schemaVersion:2};for(const t of data.tickets){t.createdAt=t.createdAt||legacyStamp(t.created);t.firstResponseAt=t.firstResponseAt||null;t.resolvedAt=t.resolvedAt||null;t.dueBy=validDue(t.dueBy||'')?t.dueBy||'':'';if(!priorities.includes(t.priority))t.priority='Normal';if(t.title==='Email example: my pay looks wrong'){t.title='Ticket example: my pay looks wrong';t.exampleType='incomplete'}if(t.exampleType==='complete'&&!t.documentMode){const example=ticketExample(true,t.id,t.createdAt);t.documentMode=example.documentMode;t.digitalForm=example.digitalForm;t.evidence=example.evidence}if(!Array.isArray(t.history))t.history=[];if(!Array.isArray(t.messages))t.messages=[];}
if(data.schemaVersion!==2){const existing=new Set(data.tickets.map(t=>t.id));for(const t of demonstrationExtras())if(!existing.has(t.id)&&!(t.exampleType&&data.tickets.some(x=>x.exampleType===t.exampleType)))data.tickets.push(t)}data.schemaVersion=2;data.next=Math.max(1043,Number(data.next)||1043,...data.tickets.map(t=>Number(t.id?.replace('HR-',''))+1||0));return data}
let state;try{state=JSON.parse(sessionStorage.getItem(KEY))}catch{}state=normaliseState(state);try{sessionStorage.setItem(KEY,JSON.stringify(state))}catch{}

let role='employee',page='home',currentId='HR-001042',filter='All',search='',replyKind='public',tab='details',selectedCategory='weekly',formData=null,lastCreated='',article='';
function save(){try{sessionStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3500)}
const button=(label,action,primary=false,extra='')=>`<button ${extra} data-action="${action}" class="${primary?'primary':''}">${label}</button>`;
const link=(label,route,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${route}">${label}</a>`;
const badge=s=>`<span class="badge ${s==='Resolved'?'green':s.startsWith('Waiting')?'amber':s==='New'?'grey':''}">${esc(s)}</span>`;
function go(route){if(location.hash.slice(1)===route)routeView();else location.hash=route}
function routeView(){if(location.hash==='#main'){document.getElementById('main').focus();return}let route=location.hash.slice(1)||'home';try{route=decodeURIComponent(route)}catch{route='home'}const parts=route.split('/');page=parts[0];if(parts[1]){if(page==='new'||page==='review'){selectedCategory=parts[1];if(formData?.cat!==selectedCategory)formData=null;}if(page==='ticket'||page==='confirmation')currentId=parts[1];if(page==='article')article=parts[1]}
if(page==='queue'||page==='reporting')role='hr';if(page==='home'||page==='catalog'||page==='new'||page==='mine'||page==='confirmation')role='employee';render();window.scrollTo(0,0)}
function nav(){const list=[...(role==='employee'?[['home','⌂','Employee portal'],['catalog','▦','Request catalogue'],['mine','▤','My requests'],['forms','▧','Forms & documents'],['help','?','Help articles']]:[['queue','▤','Team queue'],['reporting','▥','Reporting'],['forms','▧','Forms & documents']]),['journey','↗','How it works']];return list.map(([key,ic,label])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span aria-hidden="true">${ic}</span>${label}</button>`).join('')}
function head(title,subtitle,actions=''){return `<div class="topline"><div><p class="eyebrow">${role==='hr'?'HR WORKSPACE':'NOBLE FOODS'}</p><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="inlineactions">${actions}</div></div>`}
const foot=()=>`<footer>Freshservice-style HR services mockup. This is a standalone mockup, with no connection to Freshservice, Microsoft, payroll or HR records. All people and records are fictional.</footer>`;
function render(){document.getElementById('nav').innerHTML=nav();document.getElementById('empRole').className=role==='employee'?'active':'';document.getElementById('empRole').setAttribute('aria-pressed',role==='employee');document.getElementById('hrRole').className=role==='hr'?'active':'';document.getElementById('hrRole').setAttribute('aria-pressed',role==='hr');document.getElementById('avatar').textContent=role==='hr'?'AM':'JT';
const views={home,catalog,new:newRequest,review,confirmation,mine,queue,ticket,reporting,journey,help,forms:formsLibrary,article:showArticle};document.getElementById('main').innerHTML=(views[page]||home)()+foot();document.title=`${({home:'Employee portal',new:'Raise a request',ticket:currentId,queue:'HR team queue',reporting:'Reporting'})[page]||'Explore'} | Noble Foods HR Service Hub`;if(page==='queue')document.getElementById('queueSearch').value=search;}
function categoryCard(key){const c=categories[key];return `<button class="card" data-cat="${key}"><span class="arrow" aria-hidden="true">↗</span><span class="icon" aria-hidden="true">${c.icon}</span><h3>${c.name}</h3><p>${c.short}</p></button>`}
function home(){return `${head('Your HR service hub','Signed in as Jamie Taylor, a fictional employee.',link('My requests','mine'))}<section class="hero"><div><p class="eyebrow">HERE TO HELP</p><h1>Hello Jamie.<br>What can we help with?</h1><p>Choose a service and tell us what you need. We’ll give you a reference so you can keep track.</p>${link('Browse all HR services','catalog',true)}</div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="paper"><b>HR ✓</b><span></span><span></span><span></span></div></div></section><div class="sectionhead"><h2>Common requests</h2>${link('View all services','catalog')}</div><div class="cards">${['weekly','salaried','absence','details','starter','leaver'].map(categoryCard).join('')}</div><div class="bottomgrid"><section class="panel"><h2>Your recent requests</h2>${state.tickets.filter(t=>t.submitter==='Jamie Taylor').slice(0,3).map(t=>`<div class="rowlink" data-ticket="${t.id}" tabindex="0" role="link"><div><b>${esc(t.title)}</b><p>${t.id} · ${categories[t.cat].name}</p></div>${badge(t.status)}</div>`).join('')}</section><section class="panel"><h2>Before you submit</h2><p class="muted">The form will guide you through the details and any supporting information.</p><div class="callout">Mockup only. Please use fictional details. No real employee information or documents.</div>${link('Forms & documents','forms')}</section></div>`}
function catalog(){return `${head('What do you need help with?','Choose the service that best matches your request.') }<div class="callout">Each request type asks different questions and routes to a proposed HR or payroll queue.</div><div class="cards">${Object.keys(categories).map(categoryCard).join('')}</div><div class="panel" style="margin-top:22px"><h3>Employee relations</h3><p class="muted">Your ideas sheet marked ER as a topic to discuss. A separate restricted process would need agreement before including it.</p></div>`}
function inputField(field,values){const [key,label,type,example]=field;const v=values[key]??'';let control;if(type==='select')control=`<select id="${key}" name="${key}" required><option value="">Please select</option>${example.map(x=>`<option ${v===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea id="${key}" name="${key}" maxlength="2000" required>${esc(v)}</textarea>`;else control=`<input id="${key}" name="${key}" type="${type}" ${type==='number'?'min="0.01" step="0.01"':''} value="${esc(v)}" maxlength="120" required>`;return `<div class="field ${type==='textarea'?'full':''}"><label for="${key}">${label} <span aria-hidden="true">*</span></label>${control}</div>`}
function newRequest(){const c=categories[selectedCategory];if(!c)return head('Service not found','Choose a service from the catalogue.',link('Catalogue','catalog'));const v=formData?.cat===selectedCategory?formData:{};return `${head(c.name,'Step 1 of 3. Add the information HR needs.',button('Load example','fill',false))}<div class="steps"><div class="step active">1. Request details</div><div class="step">2. Review</div><div class="step">3. Confirmation</div></div><div class="twocol"><form id="requestForm" class="panel"><p class="muted">Fields marked * are required. Use fictional information only.</p><h2>Who is the request for?</h2><div class="fields"><div class="field"><label>Submitted by</label><input value="${c.manager?'Sam Ellis (demo manager)':'Jamie Taylor (demo employee)'}" readonly aria-label="Submitted by"></div><div class="field"><label for="employee">Employee concerned *</label><input id="employee" name="employee" maxlength="100" value="${esc(v.employee??(c.manager?'':'Jamie Taylor'))}" required></div><div class="field"><label for="employeeNo">Employee number ${selectedCategory==='starter'?'(if issued)':'*'}</label><input id="employeeNo" name="employeeNo" maxlength="40" value="${esc(v.employeeNo??(c.manager?'':'DEMO-1042'))}" ${selectedCategory==='starter'?'':'required'}></div><div class="field"><label for="site">Site / department *</label><input id="site" name="site" maxlength="100" value="${esc(v.site??'')}" required></div></div><h2 class="formtitle">Request details</h2><div class="fields">${c.fields.map(f=>inputField(f,v.fields||{})).join('')}</div>${requestDocuments(v)}${c.notice?`<div class="callout warning">${c.notice}</div>`:''}<div id="formError" role="alert"></div><div class="actions">${button('Save demo draft','draft',false,'type="button"')}<button type="submit" class="primary">Review request</button></div></form><div><div class="side-note"><h3>Where will it go?</h3><p>${c.group}</p><p>HR will check the details, assign an adviser and keep updates on the ticket.</p></div>${c.checklist?`<div class="panel"><h3>Starter document checklist</h3><ul class="ticklist">${c.checklist.map(x=>`<li>${x}</li>`).join('')}</ul><p class="hint">Evidence access and verification need an agreed process.</p></div>`:`<div class="panel"><h3>Information first</h3><p class="muted">A structured form helps reduce emails asking for missing dates, employee details or supporting information.</p></div>`}<div class="callout">This prototype simulates roles. It does not enforce real HR access permissions.</div></div></div>`}
function collect(){const f=document.getElementById('requestForm');if(!f)return formData;const fd=new FormData(f);const values={};for(const [k] of categories[selectedCategory].fields)values[k]=String(fd.get(k)||'').trim();return {cat:selectedCategory,employee:String(fd.get('employee')||'').trim(),employeeNo:String(fd.get('employeeNo')||'').trim(),site:String(fd.get('site')||'').trim(),fields:values,attachment:formData?.cat===selectedCategory?formData.attachment||'':'',...collectDocuments(fd)}}
function validDates(v){const documentError=validateDocuments(v);if(documentError)return documentError;const f=v.fields;if(f.start&&f.end&&f.end<f.start)return 'The end date must be on or after the start date.';if(f.leaving&&f.lastDay&&f.lastDay>f.leaving)return 'The last working day cannot be after the leaving date.';return ''}
function review(){const v=formData;if(!v)return `${head('No request to review','Start with a service and complete its form.',link('Choose a service','catalog'))}`;const c=categories[v.cat];return `${head('Check your request','Step 2 of 3. Review the details before submitting.') }<div class="steps"><div class="step">1. Request details</div><div class="step active">2. Review</div><div class="step">3. Confirmation</div></div><div class="panel"><h2>${c.name}</h2><dl class="definition"><div><dt>Submitted by</dt><dd>${c.manager?'Sam Ellis (demo manager)':'Jamie Taylor (demo employee)'}</dd></div><div><dt>Employee concerned</dt><dd>${esc(v.employee)}</dd></div><div><dt>Employee number</dt><dd>${esc(v.employeeNo||'Not yet issued')}</dd></div><div><dt>Site / department</dt><dd>${esc(v.site)}</dd></div>${c.fields.map(([k,label])=>`<div><dt>${label}</dt><dd>${esc(v.fields[k])}</dd></div>`).join('')}<div><dt>Example attachment</dt><dd>${esc(v.attachment||'None')}</dd></div><div><dt>Receiving team</dt><dd>${c.group}</dd></div></dl>${documentSummary(v)}<div class="callout">Submitting creates a fictional ticket in this browser tab. No email is sent.</div><form id="reviewForm"><label class="check"><input type="checkbox" required><span>I have checked the details and used fictional information only.</span></label><div class="actions">${button('Edit details','edit',false,'type="button"')}<button class="primary" type="submit">Submit demo request</button></div></form></div>`}
function submit(){const v=formData;if(!v)return;const c=categories[v.cat];const id='HR-'+String(state.next++).padStart(6,'0');const t={id,cat:v.cat,title:v.fields.query||v.fields.change||c.name,submitter:c.manager?'Sam Ellis':'Jamie Taylor',employee:v.employee,employeeNo:v.employeeNo||'Not yet issued',site:v.site,department:v.site,owner:'Unassigned',status:'New',priority:'Normal',source:'Portal',createdAt:stamp(),created:now(),firstResponseAt:null,resolvedAt:null,dueBy:'',fields:{...v.fields},attachment:v.attachment,documentMode:v.documentMode,digitalForm:v.digitalForm,evidence:v.evidence||[],messages:[],history:[{at:now(),text:`Request submitted and routed to ${c.group}.`}]};state.tickets.unshift(t);state.draft=null;lastCreated=id;formData=null;save();go('confirmation/'+id)}
function confirmation(){const t=state.tickets.find(x=>x.id===currentId);return !t?head('Request not found','Return to the catalogue.',link('Catalogue','catalog')):`${head('Your request is with us','Step 3 of 3. Your acknowledgement and reference.') }<div class="panel success"><div class="tick">✓</div><p class="eyebrow">DEMO REQUEST RECEIVED</p><h1>${t.id}</h1><h2>${categories[t.cat].name}</h2><p class="muted">For ${esc(t.employee)} · ${categories[t.cat].group}</p><p>You can add information and keep track on the same request.</p><div class="inlineactions" style="justify-content:center">${link('Track my request','ticket/'+t.id,true)}${button('See it in the HR queue','showHR')}</div><div class="callout">An acknowledgement confirms receipt. HR’s first substantive response is a separate step.</div></div>`}
function rows(tickets,hr=false){return tickets.map(t=>{if(!hr)return `<tr class="queue-row" tabindex="0" data-ticket="${t.id}" role="link" aria-label="Open ${t.id} ${esc(t.title)}"><td><b>${esc(t.title)}</b><small>${t.id} · ${esc(t.employee)}</small></td><td>${categories[t.cat].name}</td><td>${badge(t.status)}</td><td>${esc(formatStamp(t.createdAt))}</td></tr>`;
return `<tr><td><button class="ticket-open" data-ticket="${t.id}" aria-label="Open ${t.id} ${esc(t.title)}">${esc(t.title)}</button><small>${t.id} · ${esc(t.employee)}</small></td><td>${categories[t.cat].name}</td><td>${esc(t.owner)}</td><td>${badge(t.status)}</td><td><div class="priority-control ${t.priority.toLowerCase()}"><span aria-hidden="true">⚑</span><select data-queue-field="priority" data-queue-id="${t.id}" aria-label="Priority for ${t.id}">${priorities.map(x=>`<option value="${x}" ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></div></td><td><input class="due-input" type="date" value="${esc(t.dueBy)}" data-queue-field="dueBy" data-queue-id="${t.id}" aria-label="Due by for ${t.id}"></td><td><time datetime="${esc(t.createdAt||'')}">${esc(formatStamp(t.createdAt))}</time></td><td>${isAged(t)?'<span class="attention-flag"><span aria-hidden="true">⚑</span> Over 3 days</span>':''}${isPastDue(t)?'<span class="attention-flag overdue">Past due date</span>':''}${!isAged(t)&&!isPastDue(t)?`<span class="muted">${t.status==='Resolved'?'Resolved':'No flag'}</span>`:''}</td></tr>`}).join('')}
function mine(){const ts=state.tickets.filter(t=>t.submitter==='Jamie Taylor'||t.submitter==='Sam Ellis');return `${head('My requests','Demo view: Jamie’s requests and manager requests submitted by Sam.',link('New request','catalog',true))}<div class="panel tablewrap"><table><thead><tr><th>REQUEST</th><th>CATEGORY</th><th>STATUS</th><th>RECEIVED</th></tr></thead><tbody>${rows(ts)}</tbody></table></div>${state.draft?`<div class="callout">You have a saved demo draft. ${button('Continue draft','resume')}</div>`:''}`}
function queue(){const ts=state.tickets.filter(t=>(filter==='All'||filter==='Unassigned'&&t.owner==='Unassigned'||filter==='My tickets'&&t.owner==='Alex Morgan'||filter==='Waiting'&&t.status.startsWith('Waiting')||filter==='Over 3 days'&&isAged(t)||filter==='Past due'&&isPastDue(t)||filter==='Resolved'&&t.status==='Resolved')&&[t.id,t.title,t.employee,categories[t.cat].name,t.owner,t.priority].join(' ').toLowerCase().includes(search.toLowerCase()));const open=state.tickets.filter(t=>t.status!=='Resolved');return `${head('HR Services team queue','Demo adviser: Alex Morgan. All records shown are fictional.',button('Incomplete ticket example','email')+button('Complete ticket example','completeExample',true))}<div class="stats">${[['Open requests',open.length,'All open statuses'],['Over 3 days',open.filter(t=>isAged(t)).length,'Automatic age flag'],['Past due date',open.filter(t=>isPastDue(t)).length,'Against your manual date'],['Resolved',state.tickets.length-open.length,'Outcome recorded']].map(([l,n,h])=>`<div class="stat"><span>${l}</span><strong>${n}</strong><small>${h}</small></div>`).join('')}</div><div class="toolbar">${['All','Unassigned','My tickets','Waiting','Over 3 days','Past due','Resolved'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${f}</button>`).join('')}</div><div class="toolbar"><label class="sr-only" for="queueSearch">Search tickets</label><input id="queueSearch" type="search" placeholder="Search reference, employee, category, owner or priority…" value="${esc(search)}">${button('Search','search')}</div><div class="panel tablewrap queue-panel"><table class="hr-queue"><caption class="sr-only">HR requests with manually editable priority and due date, and automatic age flags</caption><thead><tr><th>REQUEST</th><th>CATEGORY</th><th>OWNER</th><th>STATUS</th><th>PRIORITY <small>Manual</small></th><th>DUE BY <small>Manual</small></th><th>RECEIVED</th><th>AUTO FLAGS</th></tr></thead><tbody>${rows(ts,true)}</tbody></table>${ts.length?'':'<div class="empty">No requests match this view.</div>'}</div><div class="queue-explainer"><p><b>Priority and due by:</b> edit directly in the table. Your selection saves in this browser tab.</p><p><b>Over 3 days:</b> an open ticket received more than 72 elapsed hours ago, including weekends and time waiting for information. Resolving it clears the age flag. Past due is a separate check against your chosen due date.</p></div><p class="tagline">The HR view intentionally exposes all fictional examples. A live configuration would restrict access by role and case type.</p>`}
function ticket(){const t=state.tickets.find(t=>t.id===currentId);if(!t)return head('Request not found','This demo may have been reset.',link('Start again','home'));const c=categories[t.cat];const progress=t.status==='Resolved'?4:t.status==='New'?1:2;return `${head(esc(t.title),`${t.id} · ${c.name} · ${esc(formatStamp(t.createdAt))}`,button(role==='hr'?'View as employee':'View as HR','toggleRole'))}<div class="twocol"><div><div class="panel"><div class="sectionhead" style="margin-top:0"><h2>${t.id}</h2>${badge(t.status)}</div><div class="statusstrip">${[1,2,3,4].map(i=>`<span class="${i<=progress?'done':''}"></span>`).join('')}</div><div class="statuslabels"><span>Received</span><span>HR review</span><span>Action</span><span>Resolved</span></div><div class="tabs"><button data-tab="details" class="${tab==='details'?'active':''}">Request details</button><button data-tab="conversation" class="${tab==='conversation'?'active':''}">Conversation</button><button data-tab="history" class="${tab==='history'?'active':''}">History</button></div>${tab==='details'?`<dl class="definition"><div><dt>Submitted by</dt><dd>${esc(t.submitter)}</dd></div><div><dt>Employee concerned</dt><dd>${esc(t.employee)}</dd></div><div><dt>Employee number</dt><dd>${esc(t.employeeNo)}</dd></div><div><dt>Site / department</dt><dd>${esc(t.site)}</dd></div>${c.fields.map(([k,l])=>`<div><dt>${l}</dt><dd>${esc(t.fields[k]||'Information needed')}</dd></div>`).join('')}<div><dt>Supporting document</dt><dd>${esc(t.attachment||'None')}</dd></div><div><dt>Source</dt><dd>${esc(t.source)}</dd></div></dl>${documentSummary(t)}${t.exampleType==='complete'?'<div class="callout"><b>Complete ticket example</b><br>The employee number, site, pay period, exact issue, manager contact and supporting document are all present. HR can begin its checks.</div>':''}${t.missing?'<div class="callout warning">This ticket example is missing required information. HR would request the employee number, pay period and a clear description before processing.</div>':''}${c.notice?`<div class="callout warning">${c.notice}</div>`:''}`:tab==='history'?t.history.slice().reverse().map(h=>`<div class="historyitem"><small>${esc(h.at)}</small><p>${esc(h.text)}</p></div>`).join(''):`${t.messages.filter(m=>role==='hr'||m.kind==='public').map(m=>`<div class="message ${m.kind==='internal'?'internal':''}">${m.kind==='internal'?'<p class="notesLabel">PRIVATE NOTE / HR ONLY</p>':''}<b>${esc(m.author)}</b><p class="wrap">${esc(m.text).replace(/\n/g,'<br>')}</p><small class="muted">${esc(m.at)}</small></div>`).join('')||'<p class="muted">No messages to show yet.</p>'}${role==='employee'?'<p class="hint">This employee view hides private HR notes.</p>':''}`}</div><div class="panel" style="margin-top:20px"><h2>${role==='hr'?'Add an update':'Reply or add information'}</h2>${role==='hr'?`<div class="replytabs"><button data-kind="public" aria-pressed="${replyKind==='public'}">Reply to requester</button><button data-kind="internal" aria-pressed="${replyKind==='internal'}">Private HR note</button></div>`:''}<form id="messageForm"><label for="message">${role==='hr'&&replyKind==='internal'?'Private note, visible only in this demo HR view':'Message on this request'}</label><textarea id="message" name="message" required maxlength="2000" placeholder="Use fictional information only…"></textarea><div class="actions">${role==='hr'?button('Use example wording','exampleMessage',false,'type="button"'):''}<button class="primary" type="submit">${role==='hr'&&replyKind==='internal'?'Save private note':'Send demo reply'}</button></div></form></div></div><div><div class="panel"><h3>Request ownership</h3><dl class="definition"><div><dt>Team</dt><dd>${c.group}</dd></div><div><dt>Adviser</dt><dd>${esc(t.owner)}</dd></div></dl>${role==='hr'?`<form id="updateForm"><div style="margin-top:20px"><label for="owner">Assigned adviser</label><select id="owner" name="owner">${['Unassigned','Alex Morgan','Priya Shah','HR Operations'].map(x=>`<option ${t.owner===x?'selected':''}>${x}</option>`).join('')}</select></div><div style="margin-top:15px"><label for="status">Status</label><select id="status" name="status">${statusList.map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div style="margin-top:15px"><label for="priority">Priority</label><select id="priority" name="priority">${priorities.map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div style="margin-top:15px"><label for="dueBy">Due by (manual)</label><input id="dueBy" name="dueBy" type="date" value="${esc(t.dueBy||'')}"></div><div style="margin-top:15px"><label for="resolution">Resolution summary (required to resolve)</label><textarea id="resolution" name="resolution" maxlength="1000">${esc(t.resolution||'')}</textarea></div><div class="actions"><button class="primary" type="submit">Save changes</button></div><p class="hint" id="updateError" role="alert"></p></form>`:`<div class="callout">${t.status==='Resolved'?'HR has recorded an outcome. Reply here if anything still needs checking.':t.status.startsWith('Waiting')?'HR is waiting for further information. You can reply on this request.':'Updates will stay on this ticket. You do not need to start a new request.'}</div>`}</div>${t.resolution?`<div class="side-note" style="margin-top:20px"><h3>Resolution</h3><p class="wrap">${esc(t.resolution)}</p>${role==='employee'?button('Ask HR to reopen','reopen'):''}</div>`:''}<div class="callout">${role==='hr'?'Switch to the employee view to check which messages the requester can see.':'This is a role demonstration. It is not an authenticated employee account.'}</div></div></div>`}
function reportData(tickets,clock=Date.now()){
 const today=dayKey(clock),midnight=Date.parse(today+'T00:00:00Z');
 const dates=Array.from({length:7},(_,i)=>new Date(midnight-(6-i)*DAY).toISOString().slice(0,10));
 const recent=new Set(dates),open=tickets.filter(t=>t.status!=='Resolved');
 const completed=tickets.filter(t=>t.status==='Resolved'&&recent.has(dayKey(t.resolvedAt))&&Date.parse(t.resolvedAt)<=clock);
 const timed=completed.map(t=>({t,hours:elapsedHours(t.createdAt,t.resolvedAt),reply:elapsedHours(t.createdAt,t.firstResponseAt)}));
 const durations=timed.filter(x=>x.hours!==null),replies=timed.filter(x=>x.reply!==null&&x.hours!==null&&x.reply<=x.hours);
 const mean=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;
 const services={};for(const {t,hours} of durations){const g=categories[t.cat].name;(services[g]??=[]).push(hours)}
 const status=statusList.map(name=>({name,count:tickets.filter(t=>t.status===name).length}));
 const age=[{name:'Up to 1 day',count:0},{name:'1 to 3 days',count:0},{name:'Over 3 to 7 days',count:0},{name:'Over 7 days',count:0},{name:'Date not recorded',count:0}];
 for(const t of open){const h=ageHours(t,clock);age[h===null?4:h<=24?0:h<=72?1:h<=168?2:3].count++}
 return {open,completed,avgHours:mean(durations.map(x=>x.hours)),avgReply:mean(replies.map(x=>x.reply)),timedCount:durations.length,replyCount:replies.length,days:dates.map(date=>({date,received:tickets.filter(t=>dayKey(t.createdAt)===date&&Date.parse(t.createdAt)<=clock).length,processed:completed.filter(t=>dayKey(t.resolvedAt)===date).length})),services:Object.entries(services).map(([name,xs])=>({name,count:xs.length,hours:mean(xs)})),status,age,aged:open.filter(t=>isAged(t,clock)).length};
}
function hoursLabel(n){return n===null?'Not recorded':n.toFixed(1)+' h'}
function simpleDataTable(headers,rows){return `<details class="chart-data"><summary>View chart data</summary><div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`}
function shortDay(date){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(Date.parse(date+'T12:00:00Z'))}
function trendChart(days){const max=Math.max(3,...days.map(d=>Math.max(d.received,d.processed)));return `<figure class="chart-panel"><div class="chart-heading"><div><h2>Received and processed</h2><p>Tickets by day, over the last 7 calendar dates</p></div></div><div class="chart-legend"><span><i style="background:#B6DEC0"></i>Received</span><span><i style="background:#008532"></i>Processed</span></div><div class="trend-chart" role="img" aria-label="Received and processed tickets over seven days. Exact values are shown on each bar and in the chart data table.">${days.map(d=>`<div class="trend-day"><div class="column-pair"><div class="chart-column received-column" style="height:${Math.max(1,d.received/max*100)}%" title="${shortDay(d.date)}: ${d.received} received"><span>${d.received}</span></div><div class="chart-column processed-column" style="height:${Math.max(1,d.processed/max*100)}%" title="${shortDay(d.date)}: ${d.processed} processed"><span>${d.processed}</span></div></div><span class="chart-day-label">${shortDay(d.date)}</span></div>`).join('')}</div>${simpleDataTable(['Date','Received','Processed'],days.map(d=>[shortDay(d.date),d.received,d.processed]))}</figure>`}
function serviceChart(services){const max=Math.max(1,...services.map(s=>s.hours));return `<figure class="chart-panel"><div class="chart-heading"><div><h2>Processing time by service</h2><p>Average elapsed hours for tickets resolved in the last 7 days</p></div></div>${services.length?`<div class="service-chart">${services.map(s=>`<div class="service-bar-row"><div><span>${esc(s.name)}</span><small>${s.count} completed ${s.count===1?'ticket':'tickets'}</small></div><div class="horizontal-chart-track"><i style="width:${Math.max(1,s.hours/max*100)}%"></i></div><b>${hoursLabel(s.hours)}</b></div>`).join('')}</div>`:'<p class="empty">Resolve a ticket with recorded dates to see its processing time here.</p>'}${simpleDataTable(['Service','Completed','Average hours'],services.map(s=>[s.name,s.count,s.hours.toFixed(1)]))}</figure>`}
function statusChart(status){const colours=['#9AAEA0','#00A98D','#F3BF47','#D38838','#008532'];const total=status.reduce((sum,x)=>sum+x.count,0);let offset=0;return `<figure class="chart-panel"><div class="chart-heading"><div><h2>Where the work stands</h2><p>Current status of every fictional ticket in this tab</p></div></div><div class="donut-layout"><svg viewBox="0 0 180 180" role="img" aria-label="${esc(status.map(x=>x.name+': '+x.count).join(', '))}"><title>Tickets by status</title><circle cx="90" cy="90" r="65" fill="none" stroke="#EDF3ED" stroke-width="23"/>${status.map((x,i)=>{const amount=total?x.count/total*100:0;const circle=`<circle cx="90" cy="90" r="65" fill="none" stroke="${colours[i]}" stroke-width="23" pathLength="100" stroke-dasharray="${amount} ${100-amount}" stroke-dashoffset="${-offset}" transform="rotate(-90 90 90)"/>`;offset+=amount;return amount?circle:''}).join('')}<text x="90" y="91" text-anchor="middle" fill="#173D2E" font-family="Arial" font-size="31" font-weight="bold">${total}</text><text x="90" y="114" text-anchor="middle" fill="#66796E" font-family="Arial" font-size="12">tickets</text></svg><ul class="donut-legend">${status.map((x,i)=>`<li><span class="status-key" style="background:${colours[i]}"></span><span>${esc(x.name)}</span><b>${x.count}</b></li>`).join('')}</ul></div>${simpleDataTable(['Status','Tickets'],status.map(x=>[x.name,x.count]))}</figure>`}
function ageChart(age){const max=Math.max(1,...age.map(x=>x.count));return `<figure class="chart-panel"><div class="chart-heading"><div><h2>Age of open requests</h2><p>Time since receipt, including requests waiting for information</p></div></div><div class="age-chart">${age.filter((x,i)=>i<4||x.count).map((x,i)=>`<div class="age-bar-row"><span>${x.name}</span><div class="horizontal-chart-track"><i style="width:${x.count/max*100}%;background:${i>=2?'#C37E24':'#00A98D'}"></i></div><b>${x.count}</b></div>`).join('')}</div>${simpleDataTable(['Age','Open tickets'],age.map(x=>[x.name,x.count]))}</figure>`}
function reporting(){const d=reportData(state.tickets);return `${head('Workload and reporting','Live calculations from fictional demo records in this browser tab.',button('Download demo CSV','csv',true))}<div class="report-period"><span class="badge green">Last 7 calendar dates</span><span>UK dates · elapsed hours · weekends and waiting time included</span></div><div class="stats report-stats">${[['Processed',d.completed.length,'Resolved in the last 7 days'],['Avg processing time',hoursLabel(d.avgHours),d.timedCount+' completed tickets with recorded dates'],['Avg first reply',hoursLabel(d.avgReply),d.replyCount+' completed tickets with a recorded HR reply'],['Open over 3 days',d.aged,'Automatic flag after 72 elapsed hours']].map(([label,value,hint])=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${hint}</small></div>`).join('')}</div><div class="report-charts">${trendChart(d.days)}${serviceChart(d.services)}${statusChart(d.status)}${ageChart(d.age)}</div><section class="panel report-method"><h2>How these figures work</h2><p><b>Processed</b> means currently resolved, with a resolution date in the last 7 calendar dates. <b>Processing time</b> runs from receipt to resolution. <b>First reply</b> runs from receipt to the first employee-visible HR response, rather than the automatic acknowledgement.</p><p>All times are elapsed hours, including weekends and waiting time. Tickets without usable timestamps are excluded from time averages. Reopened tickets return to the open queue and leave the processed totals until resolved again.</p><p>The completed records are fictional examples so you can explore the graphs. Changes you make in this tab update the dashboard. The CSV is a snapshot for Excel and excludes employee details, documents, descriptions and internal notes.</p></section>`}

function journey(){return `${head('How the proposed service would work','A shared process from request to outcome.') }<div class="panel article">${[['Choose the right service','Employees or managers choose a request type. The form captures employee details, relevant dates and supporting information.'],['Check completeness','Required fields reduce missing information. An emailed request may still need follow-up before HR can process it.'],['Route and assign','Weekly and salaried pay have separate proposed queues. HR allocates a named adviser, with an agreed cover arrangement.'],['Keep the conversation together','Employee-visible replies, private HR notes and the request history stay linked to one reference.'],['Record the outcome','HR records a clear resolution. The employee can reply on the same request if further work is needed.']].map(([t,d],i)=>`<div class="guide-step"><b>${i+1}</b><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div>`}
const articles={submitting:['How to raise an HR request','Choose the relevant service in the catalogue. Add the details shown as required and the appropriate supporting information. Check the summary, then submit. Keep the reference so you can follow up on the same request.'],pay:['What to include in a pay query','Choose Weekly pay or Salaried pay. Include the relevant week or month, what appears incorrect and what you need payroll to check. Use supporting records where appropriate. Do not put bank account details in the description.'],documents:['Documents and sensitive information','The live service would need approved document access and retention rules. Bank changes and health evidence need specific handling. This mockup uses example filenames only and does not upload or read any files.'],tracking:['How to check an existing request','Open My requests and select the ticket reference. Check the status and conversation. Reply there if you have more information. A resolved request can be referred back to HR if the outcome needs checking.']};
function help(){return `${head('Help with HR requests','Illustrative guidance for the proposed portal. These are not Noble Foods policies.')}<div class="widecards">${Object.entries(articles).map(([key,[t,d]])=>`<a class="card" href="#article/${key}" style="text-decoration:none"><h3>${t}</h3><p>${d.slice(0,110)}…</p></a>`).join('')}</div>`}
function showArticle(){const a=articles[article]||articles.submitting;return `${head(a[0],'Illustrative portal guidance.',link('All help articles','help'))}<article class="panel article"><p>${a[1]}</p><div class="callout">This mockup uses fictional records. Approved policy and service guidance would replace this example content.</div>${link('Browse request types','catalog',true)}</article>`}
function reset(){state={tickets:seed(),next:1043,draft:null,schemaVersion:2};formData=null;filter='All';search='';tab='details';save();document.getElementById('resetDialog').close();role='employee';go('home');toast('Demo reset. All original examples restored.')}
function eventHistory(t,text){t.history.push({at:now(),text});save()}
function csv(){const heads=['Reference','Request type','Receiving team','Owner','Status','Priority','Due by','Received at','First HR reply at','Resolved at','Processing hours','Over 3 days','Past due date','Source'];const vals=state.tickets.map(t=>[t.id,categories[t.cat].name,categories[t.cat].group,t.owner,t.status,t.priority,t.dueBy||'',t.createdAt||'',t.firstResponseAt||'',t.resolvedAt||'',t.status==='Resolved'?(elapsedHours(t.createdAt,t.resolvedAt)??''):'',isAged(t)?'Yes':'No',isPastDue(t)?'Yes':'No',t.source]);const cell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const data='\uFEFF'+[heads,...vals].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Noble-Foods-HR-demo-report.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo CSV downloaded. This is a snapshot.')}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-ticket]');if(!el)return;if(el.dataset.formStart){startDocument(el.dataset.formStart,el.dataset.formMode);return}if(el.dataset.libraryFilter){libraryFilter=el.dataset.libraryFilter;render();return}if(el.dataset.documentMode){formData=collect();formData.documentMode=el.dataset.documentMode;render();return}if(el.dataset.removeEvidence){formData=collect();formData.evidence=formData.evidence.filter((x,i)=>i!==Number(el.dataset.removeEvidence));render();return}if(el.dataset.nav){go(el.dataset.nav);return}if(el.dataset.role){role=el.dataset.role;go(role==='hr'?'queue':'home');return}if(el.dataset.cat){selectedCategory=el.dataset.cat;formData=null;go('new/'+selectedCategory);return}if(el.dataset.ticket){currentId=el.dataset.ticket;tab='details';go('ticket/'+currentId);return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.tab){tab=el.dataset.tab;render();return}if(el.dataset.kind){replyKind=el.dataset.kind;render();return}const action=el.dataset.action;if(!action)return;
if(action==='reset'){document.getElementById('resetDialog').showModal();return}if(action==='cancelReset'){document.getElementById('resetDialog').close();return}if(action==='confirmReset'){reset();return}if(action==='guided'){role='employee';selectedCategory='weekly';formData=null;go('new/weekly');return}
if(action==='fill'){const c=categories[selectedCategory];formData={cat:selectedCategory,employee:c.manager?'Morgan Reed':'Jamie Taylor',employeeNo:c.manager?'DEMO-2026':'DEMO-1042',site:'Demo site / Production',fields:Object.fromEntries(c.fields.map(([k,l,type,example])=>[k,type==='select'?example[0]:example])),attachment:'',...exampleDocuments(c,selectedCategory,formData)};render();toast('Fictional example loaded. You can edit it.');return}
if(action==='attachment'){formData=collect();formData.attachment=formData.attachment?'':categories[selectedCategory].file;render();return}if(action==='draft'){formData=collect();state.draft=formData;save();toast('Demo draft saved in this browser tab.');return}if(action==='resume'){formData=state.draft;selectedCategory=formData.cat;go('new/'+selectedCategory);return}if(action==='edit'){go('new/'+formData.cat);return}
if(action==='showHR'){role='hr';filter='All';search=currentId;go('queue');return}if(action==='toggleRole'){role=role==='hr'?'employee':'hr';replyKind='public';render();return}if(action==='search'){search=document.getElementById('queueSearch').value;render();return}if(action==='csv'){csv();return}
const t=state.tickets.find(t=>t.id===currentId);if(action==='exampleMessage'){document.getElementById('message').value=replyKind==='internal'?'Supporting record checked. Manager confirmation needed before processing.':'Thanks for the details. We have your supporting information and are checking it with your manager. We will update this request once confirmed.';return}if(action==='reopen'&&t){t.status='In progress';t.resolvedAt=null;eventHistory(t,'Requester asked HR to reopen the ticket.');t.messages.push({kind:'public',author:'Requester',at:now(),text:'Please reopen this request. I need HR to check the outcome.'});save();render();toast('Demo request reopened.');return}
if(action==='email'||action==='completeExample'){const complete=action==='completeExample';let example=state.tickets.find(x=>x.exampleType===(complete?'complete':'incomplete'));if(!example){const id='HR-'+String(state.next++).padStart(6,'0');example=ticketExample(complete,id);state.tickets.unshift(example);save()}currentId=example.id;role='hr';tab='details';go('ticket/'+example.id);toast(complete?'Complete fictional request: all processing details provided.':'Incomplete fictional email: key details still needed.');return}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-ticket]')){e.preventDefault();e.target.click()}if(e.key==='Enter'&&e.target.id==='queueSearch'){search=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='requestForm'){formData=collect();const err=validDates(formData);if(err){document.getElementById('formError').innerHTML=`<div class="formerror">${err}</div>`;return}go('review/'+selectedCategory)}else if(e.target.id==='reviewForm')submit();else if(e.target.id==='messageForm'){const t=state.tickets.find(t=>t.id===currentId),text=e.target.message.value.trim();if(!text)return;const kind=role==='hr'?replyKind:'public';if(role==='hr'&&kind==='public'&&!t.firstResponseAt)t.firstResponseAt=stamp();t.messages.push({kind,author:role==='hr'?'Alex Morgan':t.submitter,at:now(),text});eventHistory(t,kind==='internal'?'HR added a private note.':'A reply was added to the request.');tab='conversation';render();toast(kind==='internal'?'Private demo note saved.':'Demo reply added. No email sent.')}else if(e.target.id==='updateForm'){const t=state.tickets.find(t=>t.id===currentId);const fd=new FormData(e.target);const status=fd.get('status'),res=String(fd.get('resolution')||'').trim();if(status==='Resolved'&&!res){document.getElementById('updateError').textContent='Add a resolution summary before resolving.';return}const err=updateTicket(t,{owner:String(fd.get('owner')),status:String(status),priority:String(fd.get('priority')),dueBy:String(fd.get('dueBy')||''),resolution:res});if(err){document.getElementById('updateError').textContent=err;return}save();render();toast('Demo ticket updated.')}});
window.addEventListener('hashchange',routeView);routeView();

function updateTicket(t,patch,clock=Date.now()){
if(patch.priority&&!priorities.includes(patch.priority))return 'Choose a valid priority.';
if(patch.dueBy!==undefined&&!validDue(patch.dueBy))return 'Choose a valid due date.';
if(patch.status&&!statusList.includes(patch.status))return 'Choose a valid status.';
if(patch.status==='Resolved'&&!String(patch.resolution||t.resolution||'').trim())return 'Add a resolution summary before resolving.';
const previous=t.status,oldResolution=t.resolution||'';const at=new Date(clock).toISOString();
for(const k of ['owner','priority','dueBy','status'])if(patch[k]!==undefined)t[k]=patch[k];
if(patch.resolution!==undefined&&String(patch.resolution).trim())t.resolution=String(patch.resolution).trim();
if(t.status==='Resolved'){
 if(previous!=='Resolved'||!t.resolvedAt)t.resolvedAt=at;
 if(!t.firstResponseAt)t.firstResponseAt=at;
 if(previous!=='Resolved'||(patch.resolution&&patch.resolution!==oldResolution))t.messages.push({kind:'public',author:'Alex Morgan',at:formatStamp(at),text:t.resolution});
}else if(previous==='Resolved')t.resolvedAt=null;
t.history.push({at:formatStamp(at),text:`Alex Morgan updated the ticket. Owner: ${t.owner}. Status: ${t.status}. Priority: ${t.priority}. Due by: ${t.dueBy||'Not set'}.`});return '';
}
document.addEventListener('change',e=>{const el=e.target;if(!el.matches('[data-queue-field]'))return;const t=state.tickets.find(x=>x.id===el.dataset.queueId);if(!t)return;const field=el.dataset.queueField;const old=t[field];const err=updateTicket(t,{[field]:el.value});if(err){el.value=old;toast(err);return}save();render();toast(field==='priority'?'Priority saved.':'Due date saved.');});
function refreshAgeFlags(){if((page==='queue'||page==='reporting')&&!document.hidden&&!document.activeElement?.matches('input,select,textarea'))render()}
setInterval(refreshAgeFlags,60000);document.addEventListener('visibilitychange',refreshAgeFlags);

document.addEventListener('change',e=>{if(e.target.id!=='evidenceFiles')return;formData=collect();const result=addEvidence(formData.evidence||[],Array.from(e.target.files||[]));if(result.error){toast(result.error);e.target.value='';return}formData.evidence=result.files;render();toast('Demo filenames added. File contents have not been read or uploaded.');});
